import sympy as sp
A=sp.symbols('A')
e=sp.sin(A)/(1+sp.cos(A))
opts={'A':(1+sp.sin(A))/sp.cos(A),'B':(1-sp.sin(A))/sp.cos(A),'C':(1+sp.cos(A))/sp.sin(A),'D':(1-sp.cos(A))/sp.sin(A)}
pts=[0.3,0.7,1.1]
def same(f):
    return all(abs(float((e-f).subs(A,p)))<1e-12 for p in pts)
assert same(opts['D'])
for k in 'ABC': assert not same(opts[k])
